//! M4a `launch`: the host side of `src/utils/app-launcher.ts`. Long-lived apps start OUTSIDE
//! the dashboard's cgroup: on Linux through a transient user service (`systemd-run --user`,
//! never a scope), on the other platforms as a detached spawn. The argv and environment
//! builders are a byte-for-byte port of `buildSystemdRunArgs` / `systemdRunEnvironment`;
//! `tests/spec/agent/launch-table.json` (generated by the real TS functions) pins them.
//! Environment values never reach an argv: bare `--setenv=KEY` flags take the value from
//! systemd-run's own environment, exactly as the reference does.
use crate::proof;
use aac_core::{Cause, Failure};
use serde_json::{Value, json};
use std::process::{Command, Stdio};

/// One launch request, as `AppLaunchSpec` carries it. `env` keeps the JSON object's order
/// (JS insertion order; `serde_json/preserve_order`), and keys whose value was `undefined`
/// never arrive: JSON drops them, and the reference drops them too.
pub(crate) struct LaunchSpec {
    pub app: String,
    pub exe: String,
    pub args: Vec<String>,
    pub cwd: Option<String>,
    pub env: Option<Vec<(String, String)>>,
    pub log_file: Option<String>,
}

const SYSTEMD_RUN_CANDIDATES: [&str; 2] = ["/usr/bin/systemd-run", "/bin/systemd-run"];
const LOADER_ENV: [&str; 2] = ["LD_PRELOAD", "LD_LIBRARY_PATH"];
const LOADER_ENV_PREFIX: &str = "AAC_LOADER_";

/// The reference's LOADER_TRAMPOLINE: systemd expands `$NAME` before the shell runs, so
/// every `$` is doubled; the values stay off every argv and exec keeps the unit's main pid.
const LOADER_TRAMPOLINE: &str = concat!(
    "if [ \"$${AAC_LOADER_LD_PRELOAD+x}\" ]; then export LD_PRELOAD=\"$$AAC_LOADER_LD_PRELOAD\"; unset AAC_LOADER_LD_PRELOAD; fi; ",
    "if [ \"$${AAC_LOADER_LD_LIBRARY_PATH+x}\" ]; then export LD_LIBRARY_PATH=\"$$AAC_LOADER_LD_LIBRARY_PATH\"; unset AAC_LOADER_LD_LIBRARY_PATH; fi; ",
    "exec \"$$@\""
);

/// `sanitizeAppName`: lowercase, runs of non-[a-z0-9] become one '-', trimmed; empty is 'app'.
pub(crate) fn sanitize_app_name(app: &str) -> String {
    let mut cleaned = String::new();
    let mut dash = false;
    for c in app.chars() {
        let c = c.to_ascii_lowercase();
        if c.is_ascii_lowercase() || c.is_ascii_digit() {
            cleaned.push(c);
            dash = false;
        } else if !dash {
            cleaned.push('-');
            dash = true;
        }
    }
    let trimmed = cleaned.trim_matches('-');
    if trimmed.is_empty() {
        "app".into()
    } else {
        trimmed.into()
    }
}

/// `transientUnitName`.
pub(crate) fn transient_unit_name(app: &str, pid: u64, suffix: &str) -> String {
    format!("aac-launch-{}-{pid}-{suffix}", sanitize_app_name(app))
}

/// What systemd accepts as a variable name (`SYSTEMD_ENV_NAME`).
fn systemd_env_name(key: &str) -> bool {
    let mut bytes = key.bytes();
    match bytes.next() {
        Some(b'A'..=b'Z' | b'a'..=b'z' | b'_') => {}
        _ => return false,
    }
    bytes.all(|c| c.is_ascii_alphanumeric() || c == b'_')
}

/// `carriedEnvironment`: defined values with a systemd-safe name and no NUL. JSON already
/// dropped the undefined entries; the order is the object's.
fn carried_environment(env: &[(String, String)]) -> Vec<(String, String)> {
    env.iter()
        .filter(|(key, value)| systemd_env_name(key) && !value.contains('\0'))
        .cloned()
        .collect()
}

/// `unitEnvironment`: carried entries, the loader settings renamed, order kept.
fn unit_environment(env: &[(String, String)]) -> Vec<(String, String)> {
    carried_environment(env)
        .into_iter()
        .map(|(key, value)| {
            let renamed = if LOADER_ENV.contains(&key.as_str()) {
                format!("{LOADER_ENV_PREFIX}{key}")
            } else {
                key
            };
            (renamed, value)
        })
        .collect()
}

/// `buildSystemdRunArgs`, byte for byte. `--collect` drops the unit once the app exits.
pub(crate) fn build_systemd_run_args(spec: &LaunchSpec, unit: &str) -> Vec<String> {
    let mut argv = vec![
        "--user".to_string(),
        format!("--unit={unit}"),
        "--collect".to_string(),
        "--property=KillMode=process".to_string(),
    ];
    if let Some(cwd) = spec.cwd.as_deref().filter(|cwd| !cwd.is_empty()) {
        argv.push(format!("--working-directory={cwd}"));
    }
    let names: Vec<String> = match &spec.env {
        None => Vec::new(),
        Some(env) => unit_environment(env)
            .into_iter()
            .map(|(key, _)| key)
            .collect(),
    };
    for key in &names {
        argv.push(format!("--setenv={key}"));
    }
    match spec.log_file.as_deref().filter(|log| !log.is_empty()) {
        Some(log) => {
            argv.push(format!("--property=StandardOutput=append:{log}"));
            argv.push(format!("--property=StandardError=append:{log}"));
        }
        None => {
            argv.push("--property=StandardOutput=null".into());
            argv.push("--property=StandardError=null".into());
        }
    }
    argv.push("--".into());
    // systemd-run looks up word 0 itself and does not expand it; the sh step takes the path
    // as an ordinary argument when it holds a '$' or a loader setting must be restored.
    if spec.exe.contains('$') || names.iter().any(|key| key.starts_with(LOADER_ENV_PREFIX)) {
        argv.push("/bin/sh".into());
        argv.push("-c".into());
        argv.push(LOADER_TRAMPOLINE.into());
        argv.push("sh".into());
    }
    let mut command = vec![spec.exe.clone()];
    command.extend(spec.args.iter().cloned());
    argv.extend(command.iter().map(|word| word.replace('$', "$$")));
    argv
}

/// `systemdRunEnvironment`: the app's values for the bare `--setenv` flags plus the
/// inherited `XDG_RUNTIME_DIR` (how systemd-run reaches the user manager). `None` when the
/// spec names no environment, so systemd-run inherits this process's. An existing
/// `XDG_RUNTIME_DIR` key keeps its position, as a JS assignment does.
pub(crate) fn systemd_run_environment(
    spec: &LaunchSpec,
    inherited_xdg: Option<&str>,
) -> Option<Vec<(String, String)>> {
    let env = spec.env.as_ref()?;
    let mut unit = unit_environment(env);
    if let Some(xdg) = inherited_xdg.filter(|xdg| !xdg.is_empty()) {
        match unit.iter_mut().find(|(key, _)| key == "XDG_RUNTIME_DIR") {
            Some(entry) => entry.1 = xdg.to_string(),
            None => unit.push(("XDG_RUNTIME_DIR".into(), xdg.to_string())),
        }
    }
    Some(unit)
}

fn refused(message: &str) -> Failure {
    Failure::new(Cause::Refused, message)
}

/// Parse the request envelope. Unproven spellings delegate the whole verb to the TS
/// launcher; a missing required field is a refusal, as the reference's types require it.
fn parse_spec(args: &Value) -> Result<LaunchSpec, Failure> {
    let map = args
        .as_object()
        .ok_or_else(|| refused("invalid launch request"))?;
    let mut spec = LaunchSpec {
        app: String::new(),
        exe: String::new(),
        args: Vec::new(),
        cwd: None,
        env: None,
        log_file: None,
    };
    for (key, value) in map {
        match key.as_str() {
            "app" | "exe" => {
                let text = value
                    .as_str()
                    .ok_or_else(|| refused("invalid launch request"))?;
                if !proof::ascii(text) {
                    return Err(refused("invalid launch request"));
                }
                if key == "app" {
                    spec.app = text.to_string();
                } else {
                    spec.exe = text.to_string();
                }
            }
            "args" => {
                let list = value
                    .as_array()
                    .ok_or_else(|| refused("invalid launch request"))?;
                for word in list {
                    let word = word
                        .as_str()
                        .ok_or_else(|| refused("invalid launch request"))?;
                    if !proof::ascii(word) {
                        return Err(refused("invalid launch request"));
                    }
                    spec.args.push(word.to_string());
                }
            }
            "cwd" | "logFile" => {
                let text = value
                    .as_str()
                    .ok_or_else(|| refused("invalid launch request"))?;
                if !proof::ascii(text) {
                    return Err(refused("invalid launch request"));
                }
                if key == "cwd" {
                    spec.cwd = Some(text.to_string());
                } else {
                    spec.log_file = Some(text.to_string());
                }
            }
            "env" => {
                let entries = value
                    .as_object()
                    .ok_or_else(|| refused("invalid launch request"))?;
                let mut env = Vec::new();
                for (name, value) in entries {
                    let value = value
                        .as_str()
                        .ok_or_else(|| refused("invalid launch request"))?;
                    // The reference drops NUL-carrying entries instead of failing; other
                    // control bytes ride along as spawn carries them. Non-ASCII is unproven.
                    if !name.bytes().all(|c| c <= 0x7f) || !value.bytes().all(|c| c <= 0x7f) {
                        proof::reject();
                        return Err(refused("invalid launch request"));
                    }
                    env.push((name.clone(), value.to_string()));
                }
                spec.env = Some(env);
            }
            // Fixture overrides exist only in parity builds (AppLauncherDeps' test seams).
            #[cfg(feature = "parity-fixtures")]
            "platform" | "systemdRunPath" | "pid" | "suffix" => {}
            _ => {
                proof::reject();
                return Err(refused("invalid launch request"));
            }
        }
    }
    if spec.app.is_empty() || spec.exe.is_empty() {
        return Err(refused("invalid launch request"));
    }
    Ok(spec)
}

/// The reference's `defaultRandomSuffix` shape: eight lowercase base36 digits. The digest
/// source is private; only the shape is contractual (the parity table pins fixed suffixes).
fn random_suffix() -> String {
    use sha2::{Digest, Sha256};
    static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let seq = SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let digest = Sha256::digest(format!("{nanos}:{seq}:{}", std::process::id()).as_bytes());
    digest.iter().take(4).map(|b| format!("{b:02x}")).collect()
}

/// The systemd-run the reference would use: the first candidate with an execute bit.
fn default_systemd_run_path() -> Option<String> {
    for candidate in SYSTEMD_RUN_CANDIDATES {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            if let Ok(meta) = std::fs::metadata(candidate) {
                if meta.is_file() && meta.permissions().mode() & 0o111 != 0 {
                    return Some(candidate.to_string());
                }
            }
        }
        #[cfg(not(unix))]
        {
            let _ = candidate;
        }
    }
    None
}

/// What the reference's `launchApp` does with the plan, minus the platform probe: the
/// direct route spawns detached with discarded output; the systemd route waits for exit 0.
fn execute(
    spec: &LaunchSpec,
    platform: &str,
    systemd_run_path: Option<&str>,
    pid: u64,
    suffix: &str,
) -> Result<Value, Failure> {
    if platform != "linux" {
        let mut command = Command::new(&spec.exe);
        command
            .args(&spec.args)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        if let Some(cwd) = &spec.cwd {
            command.current_dir(cwd);
        }
        if let Some(env) = &spec.env {
            command.env_clear();
            for (key, value) in env {
                command.env(key, value);
            }
        }
        // Node's `detached: true` plus `unref`: a new process group, and the child outlives
        // this process. Rust never kills on drop, which is the unref.
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            command.process_group(0);
        }
        #[cfg(windows)]
        {
            use std::os::windows::process::CommandExt;
            // CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS, as Node's detached spawn.
            command.creation_flags(0x0000_0200 | 0x0000_0008);
        }
        let child = command.spawn().map_err(|_| {
            refused(&format!(
                "Cannot launch {} outside the dashboard cgroup: the app failed to start.",
                spec.app
            ))
        })?;
        return Ok(json!({"route": "direct", "pid": child.id()}));
    }
    let Some(systemd_run) = systemd_run_path else {
        return Err(refused(&format!(
            "Cannot launch {} outside the dashboard cgroup: systemd-run is unavailable. Refusing to start it inside ccs-dashboard.service, where a dashboard restart would kill it.",
            spec.app
        )));
    };
    let unit = transient_unit_name(&spec.app, pid, suffix);
    let argv = build_systemd_run_args(spec, &unit);
    let mut command = Command::new(systemd_run);
    command
        .args(&argv)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    if let Some(env) =
        systemd_run_environment(spec, std::env::var("XDG_RUNTIME_DIR").ok().as_deref())
    {
        command.env_clear();
        for (key, value) in env {
            command.env(key, value);
        }
    }
    let status = command.status().map_err(|_| {
        refused(&format!(
            "Cannot launch {} outside the dashboard cgroup: systemd-run failed to start.",
            spec.app
        ))
    })?;
    if !status.success() {
        let code = status
            .code()
            .map(|c| c.to_string())
            .unwrap_or_else(|| "null".into());
        return Err(refused(&format!(
            "Cannot launch {} outside the dashboard cgroup: systemd-run exited with code {code}.",
            spec.app
        )));
    }
    Ok(json!({"route": "systemd-service", "unit": unit}))
}

pub(crate) fn run(args: &Value) -> Result<Value, Failure> {
    // The proof scope covers the whole verb: an unproven spelling delegates it to the
    // TS launcher, which owns every non-ASCII path and environment.
    let mut outcome: Result<Value, Failure> = Ok(json!({}));
    let value = proof::scope(|| {
        outcome = run_inner(args);
        outcome.clone().unwrap_or_else(|_| json!({}))
    });
    if value == proof::fallback() {
        Ok(proof::fallback())
    } else {
        outcome
    }
}

fn run_inner(args: &Value) -> Result<Value, Failure> {
    let spec = parse_spec(args)?;
    // Production: this computer's own platform, pid and a fresh suffix; the systemd-run
    // probe. Parity builds may pin each of them, as AppLauncherDeps does for the TS tests.
    #[cfg(feature = "parity-fixtures")]
    let (platform, systemd_run_path, pid, suffix) = {
        let platform = match args.get("platform") {
            None => own_platform().to_string(),
            Some(Value::String(p))
                if matches!(p.as_str(), "linux" | "darwin" | "win32" | "mac" | "windows") =>
            {
                p.clone()
            }
            _ => return Ok(proof::fallback()),
        };
        let systemd_run_path = match args.get("systemdRunPath") {
            None => default_systemd_run_path(),
            Some(Value::Null) => None,
            Some(Value::String(p)) if proof::ascii(p) => Some(p.clone()),
            _ => return Ok(proof::fallback()),
        };
        let pid = match args.get("pid") {
            None => u64::from(std::process::id()),
            Some(v) => match v.as_u64() {
                Some(pid) if pid > 0 => pid,
                _ => return Ok(proof::fallback()),
            },
        };
        let suffix = match args.get("suffix") {
            None => random_suffix(),
            Some(Value::String(s))
                if !s.is_empty() && s.bytes().all(|c| c.is_ascii_alphanumeric()) =>
            {
                s.clone()
            }
            _ => return Ok(proof::fallback()),
        };
        (platform, systemd_run_path, pid, suffix)
    };
    #[cfg(not(feature = "parity-fixtures"))]
    let (platform, systemd_run_path, pid, suffix) = (
        own_platform().to_string(),
        default_systemd_run_path(),
        u64::from(std::process::id()),
        random_suffix(),
    );
    let platform = if platform == "mac" {
        "darwin"
    } else if platform == "windows" {
        "win32"
    } else {
        platform.as_str()
    };
    execute(&spec, platform, systemd_run_path.as_deref(), pid, &suffix)
}

fn own_platform() -> &'static str {
    if cfg!(target_os = "linux") {
        "linux"
    } else if cfg!(target_os = "macos") {
        "darwin"
    } else if cfg!(windows) {
        "win32"
    } else {
        "unsupported"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sanitize_and_unit_names_match_the_reference() {
        assert_eq!(sanitize_app_name("Codex CLI!"), "codex-cli");
        assert_eq!(sanitize_app_name("!!!"), "app");
        assert_eq!(sanitize_app_name(""), "app");
        assert_eq!(sanitize_app_name("--A--B--"), "a-b");
        assert_eq!(
            transient_unit_name("codex-cli", 999, "abc123"),
            "aac-launch-codex-cli-999-abc123"
        );
    }

    #[test]
    fn loader_trampoline_is_the_reference_text() {
        // The TS constant, written out once here so a drift in either copy fails the table.
        let reference = [
            "if [ \"$${AAC_LOADER_LD_PRELOAD+x}\" ]; then export LD_PRELOAD=\"$$AAC_LOADER_LD_PRELOAD\"; unset AAC_LOADER_LD_PRELOAD; fi",
            "if [ \"$${AAC_LOADER_LD_LIBRARY_PATH+x}\" ]; then export LD_LIBRARY_PATH=\"$$AAC_LOADER_LD_LIBRARY_PATH\"; unset AAC_LOADER_LD_LIBRARY_PATH; fi",
            "exec \"$$@\"",
        ]
        .join("; ");
        assert_eq!(LOADER_TRAMPOLINE, reference);
    }

    #[test]
    fn xdg_runtime_dir_keeps_an_existing_keys_position() {
        let spec = LaunchSpec {
            app: "app".into(),
            exe: "/bin/true".into(),
            args: vec![],
            cwd: None,
            env: Some(vec![
                ("XDG_RUNTIME_DIR".into(), "/run/user/stale".into()),
                ("KEEP".into(), "yes".into()),
            ]),
            log_file: None,
        };
        let env = systemd_run_environment(&spec, Some("/run/user/dashboard")).expect("env");
        assert_eq!(
            env,
            vec![
                ("XDG_RUNTIME_DIR".into(), "/run/user/dashboard".into()),
                ("KEEP".into(), "yes".into()),
            ]
        );
        assert!(systemd_run_environment(&LaunchSpec { env: None, ..spec }, Some("/x")).is_none());
    }

    /// The M4a gate: every row of the table the real TS builders wrote must equal the port.
    #[test]
    fn launch_table_matches_the_ts_builders() {
        let table: Value =
            serde_json::from_str(include_str!("../../../tests/spec/agent/launch-table.json"))
                .expect("launch table parses");
        let cases = table["cases"].as_array().expect("cases");
        assert!(cases.len() >= 48, "every app shape on every OS");
        for case in cases {
            let name = case["name"].as_str().expect("name");
            let spec = parse_spec(&case["spec"]).unwrap_or_else(|_| panic!("{name}: spec"));
            let expected = &case["expected"];
            assert_eq!(
                sanitize_app_name(&spec.app),
                expected["sanitized"].as_str().expect("sanitized"),
                "{name}: sanitized"
            );
            let pid = case["pid"].as_u64().expect("pid");
            let suffix = case["suffix"].as_str().expect("suffix");
            let unit = transient_unit_name(&spec.app, pid, suffix);
            assert_eq!(
                unit,
                expected["unit"].as_str().expect("unit"),
                "{name}: unit"
            );
            let argv = build_systemd_run_args(&spec, &unit);
            let want: Vec<String> = expected["argv"]
                .as_array()
                .expect("argv")
                .iter()
                .map(|w| w.as_str().expect("word").to_string())
                .collect();
            assert_eq!(argv, want, "{name}: argv");
            let inherited = case["inheritedXDG"].as_str();
            let env = systemd_run_environment(&spec, inherited);
            match &expected["envEntries"] {
                Value::Null => assert!(env.is_none(), "{name}: env must inherit"),
                entries => {
                    let want: Vec<(String, String)> = entries
                        .as_array()
                        .expect("entries")
                        .iter()
                        .map(|pair| {
                            (
                                pair[0].as_str().expect("key").to_string(),
                                pair[1].as_str().expect("value").to_string(),
                            )
                        })
                        .collect();
                    assert_eq!(env.expect("env"), want, "{name}: env entries");
                }
            }
        }
    }
}
